int main(){
vector<double> outcome={2,4,5,3,9,6};
vector<int> information={0,0,0,1,1,1};
double sum[2]={0,0};int count[2]={0,0};
for(int i=0;i<int(outcome.size());i++){
    sum[information[i]]+=outcome[i];
    count[information[i]]++;
}
