#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
vector<double> a={1,3,1,3},b={2,2.5,1.5,2};
double meanA=0,meanB=0;
for(int i=0;i<int(a.size());i++){meanA+=a[i]/a.size();meanB+=b[i]/b.size();}
double va=0,vb=0,cov=0;
for(int i=0;i<int(a.size());i++){
    va+=pow(a[i]-meanA,2)/a.size();
    vb+=pow(b[i]-meanB,2)/a.size();
    cov+=(a[i]-meanA)*(b[i]-meanB)/a.size();
}
cout<<"Var ensemble "<<(va+vb+2*cov)/4
    <<" individual variance "<<va<<" "<<vb<<endl;
    return 0;
}

