#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
vector<vector<double>> chain={{1,1.1,0.9,1.2,1.05},{1.02,1.08,0.96,1.12,1.00},
    {1.1,1.07,0.94,1.14,1.03}};
int m=chain.size(),n=chain[0].size();
vector<double> means(m,0);
double grand=0,within=0,between=0;
for(int i=0;i<m;i++){
    for(double value:chain[i])means[i]+=value/n;
    grand+=means[i]/m;
    double variance=0;
    for(double value:chain[i])variance+=pow(value-means[i],2)/(n-1);
    within+=variance/m;
}
for(double mean:means)between+=n*pow(mean-grand,2)/(m-1);
double varianceEstimate=(n-1.0)/n*within+between/n;
if(within<=0)return 1;
cout<<"W "<<within<<" B "<<between<<" R-hat "<<sqrt(varianceEstimate/within)<<endl;
    return 0;
}

