#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
vector<vector<double>> embeddings={{1,0},{0.9,0.1},{0,1},{0.1,0.9}};
vector<int> positive={1,0,3,2};
double temperature=0.2,loss=0;
for(int i=0;i<int(embeddings.size());i++){
    double maximum=-1e100;
    vector<double> similarities(embeddings.size(),0);
    for(int j=0;j<int(embeddings.size());j++)if(i!=j){
        for(int k=0;k<2;k++)similarities[j]+=embeddings[i][k]*embeddings[j][k];
        similarities[j]/=temperature;
        maximum=max(maximum,similarities[j]);
    }
    double denominator=0;
    for(int j=0;j<int(embeddings.size());j++)
        if(i!=j)denominator+=exp(similarities[j]-maximum);
    loss+=-(similarities[positive[i]]-maximum-log(denominator))/embeddings.size();
}
cout<<"Contrastive loss "<<loss<<endl;
    return 0;
}

