#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
vector<vector<double>> tokens={{1,0},{0,1},{1,1}};
vector<double> cls=tokens[0],score(tokens.size(),0);
for(int i=0;i<int(tokens.size());i++){
    for(int k=0;k<int(cls.size());k++)score[i]+=cls[k]*tokens[i][k]/sqrt(2.0);
}
double peak=*max_element(score.begin(),score.end()),denom=0;
for(double s:score)denom+=exp(s-peak);
vector<double> output(cls.size(),0);
for(int i=0;i<int(tokens.size());i++){
    double probability=exp(score[i]-peak)/denom;
    for(int k=0;k<int(cls.size());k++)output[k]+=probability*tokens[i][k];
}
cout<<"Encoded CLS "<<output[0]<<" "<<output[1]<<endl;
    return 0;
}

