#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
double reward[2][2]={{1,0},{0,2}};
int next[2][2]={{0,1},{0,1}},policy[2]={0,0};
double value[2]={0,0},gamma=0.9;
for(int iteration=0;iteration<30;iteration++){
    for(int step=0;step<100;step++){
        double update[2];
        for(int s=0;s<2;s++)update[s]=reward[s][policy[s]]+gamma*value[next[s][policy[s]]];
        value[0]=update[0];value[1]=update[1];
    }
    bool changed=false;
    for(int s=0;s<2;s++){
        double q0=reward[s][0]+gamma*value[next[s][0]];
        double q1=reward[s][1]+gamma*value[next[s][1]];
        int selected=q1>q0?1:0;
        changed|=selected!=policy[s];
        policy[s]=selected;
    }
    if(!changed)break;
}
cout<<"Policy "<<policy[0]<<" "<<policy[1]
    <<" values "<<value[0]<<" "<<value[1]<<endl;
    return 0;
}

