for(double a0:actions)for(double a1:actions)for(double a2:actions){
    double state=0,total=0;
    for(double action:{a0,a1,a2}){
        state=0.8*state+action;
        total-=state*state+0.1*action*action;
    }
    if(total>best){best=total;bestFirst=a0;}
}
cout<<"Best initial action "<<bestFirst<<" utility "<<best<<endl;
    return 0;
}

