#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
vector<double> before={0.6,0.4},returnAsset={0.1,-0.05};
vector<double> target={0.5,0.5};
double portfolioGrowth=0;
for(int i=0;i<int(before.size());i++)portfolioGrowth+=before[i]*(1+returnAsset[i]);
double grossTraded=0;
for(int i=0;i<int(before.size());i++){
    double drifted=before[i]*(1+returnAsset[i])/portfolioGrowth;
    grossTraded+=fabs(target[i]-drifted);
    cout<<"Asset "<<i<<" drifted "<<drifted<<endl;
}
cout<<"One-way turnover "<<grossTraded/2<<endl;
    return 0;
}
